import{_ as d,o,c as t,a2 as s}from"./chunks/framework.BS2VDJqE.js";const u=JSON.parse('{"title":"词形还原（Hunspell）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/word-forms.md","filePath":"zh/guide/word-forms.md","lastUpdated":1795797533000}'),a={name:"zh/guide/word-forms.md"};function l(c,e,i,h,n,r){return o(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="词形还原-hunspell" tabindex="-1">词形还原（Hunspell） <a class="header-anchor" href="#词形还原-hunspell" aria-label="Permalink to &quot;词形还原（Hunspell）&quot;">​</a></h1><p>词形还原会把变形词追溯到原形：查 <code>hoped</code> 也能找到 <code>hope</code>，查 <code>reconstructiveness</code> 也能找到 <code>reconstruct</code>。</p><p>这个功能<strong>默认关闭</strong>，且需要外部的 Hunspell 文件。原因是词形还原发生在 「引擎层」而不是词典内容里：不需要往 <code>.mdx</code> 里塞变形表，只要你能找到某种语言的 Hunspell <code>.aff</code>/<code>.dic</code>，那种语言就能用。</p><h2 id="能做什么" tabindex="-1">能做什么 <a class="header-anchor" href="#能做什么" aria-label="Permalink to &quot;能做什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>查询</th><th>结果</th></tr></thead><tbody><tr><td><code>hoped</code></td><td><code>hoped</code>（精确词条）+ <code>hope</code>（原形）</td></tr><tr><td><code>rims</code></td><td><code>RIMS</code>（精确词条）+ <code>rim</code>（原形）</td></tr><tr><td><code>fällt</code>（德）</td><td><code>fällt</code> + <code>fallen</code> / <code>fällen</code></td></tr><tr><td><code>abgekämpft</code>（德）</td><td><code>abkämpfen</code></td></tr><tr><td><code>かって</code>（日）</td><td><code>かって（勝手）</code> / <code>かう（買う）</code> / <code>かつ（勝つ）</code> / <code>かる（狩る）</code></td></tr><tr><td><code>闲适</code>（中）</td><td><code>闲适</code>（精确词条）+ 词表里声明的各种写法，例如 <code>閒適</code></td></tr></tbody></table><p>能还原出几个原形，完全取决于你用的 Hunspell 文件——一个形式真有多个词干时， 就会全部列出。这其中有些是词悦自己的改动：原版 Hunspell 会丢掉一部分， 见<a href="./../internals/word-forms.html">「词悦使用的 Hunspell」</a>。</p><h2 id="怎么开启" tabindex="-1">怎么开启 <a class="header-anchor" href="#怎么开启" aria-label="Permalink to &quot;怎么开启&quot;">​</a></h2><ol><li><strong>设置 → Hunspell</strong> —— 打开「启用词形还原与变体查找」；</li><li>导入 <code>.aff</code> + <code>.dic</code>：选择包含这些文件的文件夹，每种语言一对，应用不内置任何文件；</li><li>选择查找模式（见下）。对多数人来说更有用的是**补充（Supplement）**模式。</li></ol><p>词干查询在后台执行，开启后不会拖慢界面。</p><h2 id="编码" tabindex="-1">编码 <a class="header-anchor" href="#编码" aria-label="Permalink to &quot;编码&quot;">​</a></h2><p>词悦把查询词以 UTF-8 传给 Hunspell，并把结果按 UTF-8 解码；这一层不会在编码之间做转换。因此 <code>.aff</code> 必须声明 <code>SET UTF-8</code>，<code>.dic</code> 也必须实际以 UTF-8 保存。</p><p>旧编码的词典仍然能导入，纯 ASCII 词也可能正常，但带重音或西里尔字母的词会还原不出来。一些老的 GoldenDict 资源就有这个问题，例如 “better morphologies” 1.0 里的 <code>es_ES</code> 是 ISO-8859-1、<code>ru_RU</code> 是 KOI8-R。导入前请把两个文件一起转成 UTF-8：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 以 ISO-8859-1 为例；实际请用原 SET 行声明的编码</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iconv</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ISO-8859-1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> UTF-8</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> es_ES.aff</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;s/^SET .*/SET UTF-8/&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> es_ES.aff.utf8</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iconv</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ISO-8859-1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> UTF-8</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> es_ES.dic</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> es_ES.dic.utf8</span></span></code></pre></div><p>确认几个非 ASCII 词能查后，再替换原文件。<code>SET UTF-8</code> 要用大写，也不要加 BOM。GitHub raw 返回的是仓库里提交的原始字节，所以仓库里要存转换后的 UTF-8 文件。</p><h2 id="兜底-vs-补充" tabindex="-1">兜底 vs 补充 <a class="header-anchor" href="#兜底-vs-补充" aria-label="Permalink to &quot;兜底 vs 补充&quot;">​</a></h2><table tabindex="0"><thead><tr><th>查询</th><th>兜底（默认）</th><th>补充</th></tr></thead><tbody><tr><td><code>rims</code></td><td>只显示 <code>RIMS</code> 这条词条</td><td><code>RIMS</code> + <code>rim</code></td></tr><tr><td><code>hoped</code></td><td>只显示 <code>hoped</code> 这条词条</td><td><code>hoped</code> + <code>hope</code></td></tr></tbody></table><p><strong>兜底</strong>的意思是：只有当某本词典没有精确词条时，才去尝试还原词干。所以一旦词典里 恰好有 <code>RIMS</code> 或 <code>hoped</code> 做词条，原形就永远不会被查出来。<strong>补充</strong>则始终把词干和精确 词条并列显示，这也是 GoldenDict 的行为。</p><p>如果同一个词在一种模式下能查到、另一种查不到，先检查这个开关。</p><h2 id="去哪找-hunspell-文件" tabindex="-1">去哪找 Hunspell 文件 <a class="header-anchor" href="#去哪找-hunspell-文件" aria-label="Permalink to &quot;去哪找 Hunspell 文件&quot;">​</a></h2><p>系统（例如Debian）自带的Hunspell词典文件通常只为拼写检查设计，<strong>没有手写的 <code>st:</code> 条目</strong>，不规则变形根本无法还原。可用的维护版本：</p><ul><li>英文：<a href="https://github.com/yx-wh/hunspell_en_US" target="_blank" rel="noreferrer">https://github.com/yx-wh/hunspell_en_US</a> —— 修正了错误的后缀标签、补齐 词干链接与派生标签，并扩充了词表。</li><li>德文：<a href="https://github.com/yx-wh/hunspell_de_DE" target="_blank" rel="noreferrer">https://github.com/yx-wh/hunspell_de_DE</a> —— 为可分动词的分词、<code>zu</code> 不定式补了 2,000 多条 <code>st:</code>。</li><li>日文：<a href="https://github.com/yx-wh/hunspell_ja_JP" target="_blank" rel="noreferrer">https://github.com/yx-wh/hunspell_ja_JP</a> —— 由于日文通常无需拼写检查，需要单独为日文设计Hunspell词典文件。这个版本在Gary原始版本的基础上增加了混书形式到汉字的还原（例如「まん延」→「蔓延」）、补充了一些动词的活用、补充了半角假名。</li><li>中文：<a href="https://github.com/yx-wh/hunspell_zh_CN" target="_blank" rel="noreferrer">https://github.com/yx-wh/hunspell_zh_CN</a> —— 空壳 <code>.aff</code> 加一份从多部中文词典生成的 <code>st:</code> 表。仓库发布的 <code>zh_CN.dic</code> 是精简版，词悦和 GoldenDict-ng 用它就够；既不按字组合、也不走 OpenCC 的读取器，需要用仓库里的脚本自行生成全量表。</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>打开后毫无变化。</strong> 按顺序检查三件事：开关、是否导入了 <code>.aff</code>/<code>.dic</code>、当前查找 模式。在「兜底」模式下，有精确命中的词看起来和没开这个功能一模一样。</p><p><strong>查 <code>hoped</code> 还会出 <code>hop</code>。</strong> 系统（如Debian）自带Hunspell词典文件上挂着 <code>hop/D</code> 标签，而这套 <code>.aff</code> 不做辅音双写，于是 <code>hop + ed</code> 也生成了 <code>hoped</code>（正确形式应是 <code>hopped</code>）。换用 上面修正过的英文词典即可，或者自己把 <code>hop</code> 上的 <code>D</code> 去掉。</p><p><strong>德语 <code>fällt</code> 只出一个原形。</strong> <code>fallen</code> 和 <code>fällen</code> 的第三人称单数都是 <code>fällt</code>， 但 Hunspell 只能报出 <code>.dic</code> 里声明过的内容；没有对应 <code>st:</code> 条目的词典就会少给。</p><p><strong><code>abzukämpfen</code> / <code>abgekämpft</code> 还原不出来。</strong> 可分动词的 <code>zu</code> 和 <code>ge</code> 是中缀， Hunspell 剥不掉，必须用 <code>st:</code> 显式标注，见上面的德文词典。</p><p><strong>一个拼写写了两条 <code>st:</code>，只回来一个原形。</strong> 如果 <code>.dic</code> 把同一个词写了两遍、 <code>st:</code> 不同、又都没挂 flag，原版构建只返回第一个：它的 <code>stem()</code> 只取一条分析记 录里的第一个 <code>st:</code> 字段；词悦打过补丁的版本两条都会保留，见 <a href="./../internals/word-forms.html">「词悦使用的 Hunspell」</a>。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="./../internals/word-forms.html">词形还原的实现</a> —— 词悦内置的 Hunspell 补丁、中文异体字表的设计、NFC 归一化，以及直接测试词典。</li><li><a href="./faq.html">常见问题</a> —— 词典与显示相关的问题。</li><li><a href="./getting-started.html">快速上手</a> —— 添加词典。</li></ul>`,29)])])}const k=d(a,[["render",l]]);export{u as __pageData,k as default};
